#pragma once

// The boot menu disk (Issue #38): a 720 x 128 ATR held in memory. Sectors 1 to
// kMenuLoadSectors are the 6502 menu block generated by tools/make_menu.py, with
// the catalog written into its entry lines; every other sector reads as zeros.

#include <array>
#include <cstddef>
#include <cstdint>

#include "menu_catalog.hpp"
#include "rb/core/result.hpp"
#include "rb/core/span.hpp"
#include "rb/domain/image_byte_source.hpp"

namespace rb::host {

#include "menu_program.inc"

constexpr std::size_t kMenuHeaderSize = 16;
constexpr uint32_t kMenuSectors = 720;
constexpr uint32_t kMenuImageSize = kMenuHeaderSize + kMenuSectors * 128;
constexpr std::size_t kMenuNameColumns = 30;  // longer names are cut

// One mode 2 line: ATASCII 0x20-0x7E to screen codes, left-aligned, padded with
// spaces; anything else is shown as '?'. Lowercase letters are shown uppercase.
void screenLine(const char* text, rb::core::Span<uint8_t> line) noexcept;

class MenuImage final : public rb::domain::ImageByteSource {
public:
    explicit MenuImage(const MenuCatalog& catalog) noexcept;

    uint32_t size() const override { return kMenuImageSize; }
    rb::core::Result<void> readAt(uint32_t offset, rb::core::Span<uint8_t> out) override;

    // The loaded block as the Atari sees it (for tests).
    const std::array<uint8_t, sizeof kMenuBlock>& block() const noexcept { return block_; }

private:
    std::array<uint8_t, sizeof kMenuBlock> block_{};
};

}  // namespace rb::host
